// 1) Утилиты, которые реально используются в бэкенде
type Nullable<T> = { [K in keyof T]: T[K] | null };
type PartialBy<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>;
type ReadonlyDeep<T> = T extends (infer U)[] ? readonly ReadonlyDeep<U>[]
  : T extends object ? { readonly [K in keyof T]: ReadonlyDeep<T[K]> } : T;

// 2) Типобезопасный "патч" для PATCH-запросов
const patchUser = <T extends object>(base: T, patch: Partial<T>): T => ({ ...base, ...patch });

// 3) infer — извлечение типа возвращаемого значения хендлера
type AsyncReturn<F> = F extends (...args: any[]) => Promise<infer R> ? R : never;

// 4) Discriminated union для состояний заказа — исключает "невозможные" состояния
type Order =
  | { status: 'created'; paymentId: string }
  | { status: 'paid'; paidAt: Date; paymentId: string }
  | { status: 'cancelled'; reason: string };

function ship(order: Order): string {
  if (order.status !== 'paid') throw new Error('order is not payable'); // узкий тип внутри ветки
  return `shipping order paid at ${order.paidAt.toISOString()}`;
}

import { z } from 'zod';

export const CreateOrderSchema = z.object({
  customerId: z.uuid(),
  items: z.array(z.object({
    sku: z.string().regex(/^[A-Z0-9-]{6,24}$/),
    qty: z.int().positive().max(999),
    priceCents: z.int().nonnegative(),
  })).min(1).max(100),
  coupon: z.string().max(32).optional(),
  metadata: z.record(z.string(), z.unknown()).optional(),
}).superRefine((val, ctx) => {
  const sum = val.items.reduce((s, i) => s + i.priceCents * i.qty, 0);
  if (sum === 0) ctx.addIssue({ code: 'custom', message: 'total must be > 0', path: ['items'] });
});

export type CreateOrderDto = z.infer<typeof CreateOrderSchema>;   // вход в сервис
export type CreateOrderView = z.output<typeof CreateOrderSchema>; // то, что уходит дальше
